--
-- Table structure for table `fico_company_relation`
--

DROP TABLE IF EXISTS `fico_company_relation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fico_company_relation` (
  `FICO_RELATION_ID` bigint NOT NULL AUTO_INCREMENT,
  `FI_COMPANY_ID` bigint NOT NULL,
  `CO_COMPANY_ID` bigint NOT NULL,
  `COSTING_VARIANT` varchar(50) DEFAULT NULL,
  `COST_CURRENCY` char(3) DEFAULT NULL,
  `ALLOW_INTERNAL_ORDERS` tinyint(1) DEFAULT '0',
  `REQUIRE_COST_CENTER` tinyint(1) DEFAULT '0',
  `COST_CENTER_PLAN` bigint DEFAULT NULL,
  `RELATION_TYPE` enum('STANDARD','SERVICE','COST_SHARING','TRANSFER','PROJECT') DEFAULT NULL,
  `FICO_VALID_FROM` date DEFAULT NULL,
  `FICO_VALID_TO` date DEFAULT NULL,
  `FICO_STATUS` enum('ACTIVE','INACTIVE') DEFAULT NULL,
  `FICO_CREATED_BY` varchar(50) DEFAULT NULL,
  `FICO_CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP,
  `FICO_UPDATED_BY` varchar(50) DEFAULT NULL,
  `FICO_UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`FICO_RELATION_ID`,`FI_COMPANY_ID`,`CO_COMPANY_ID`),
  KEY `FK_FICO_CREATED_BY` (`FICO_CREATED_BY`),
  KEY `FK_FICO_UPDATED_BY` (`FICO_UPDATED_BY`),
  KEY `FK_FICO_CO_COMPANY` (`CO_COMPANY_ID`),
  KEY `FK_FICO_FI_COMPANY` (`FI_COMPANY_ID`),
  KEY `FK_FICO_COST_CENTER_PLAN` (`COST_CENTER_PLAN`),
  CONSTRAINT `FK_FICO_CO_COMPANY` FOREIGN KEY (`CO_COMPANY_ID`) REFERENCES `co_company` (`CO_COMPANY_ID`),
  CONSTRAINT `FK_FICO_COST_CENTER_PLAN` FOREIGN KEY (`COST_CENTER_PLAN`) REFERENCES `cost_center_plan` (`ID`),
  CONSTRAINT `FK_FICO_CREATED_BY` FOREIGN KEY (`FICO_CREATED_BY`) REFERENCES `users` (`USERNAME`),
  CONSTRAINT `FK_FICO_FI_COMPANY` FOREIGN KEY (`FI_COMPANY_ID`) REFERENCES `fi_company` (`FI_COMPANY_ID`),
  CONSTRAINT `FK_FICO_UPDATED_BY` FOREIGN KEY (`FICO_UPDATED_BY`) REFERENCES `users` (`USERNAME`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

