--
-- Table structure for table `ordenes_de_mantenimiento`
--

DROP TABLE IF EXISTS `ordenes_de_mantenimiento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ordenes_de_mantenimiento` (
  `NUM_ORDER` int NOT NULL AUTO_INCREMENT,
  `DESCRIPCION_ORDEN` varchar(200) NOT NULL,
  `ID_ESTATUS` varchar(5) NOT NULL,
  `ESTATUS` varchar(35) NOT NULL,
  `ID_TIPO_MTTO` varchar(45) NOT NULL,
  `TIPO_MTTO` varchar(45) NOT NULL,
  `ID_CLASE_MTTO` varchar(45) NOT NULL,
  `CLASE_MTTO` varchar(20) NOT NULL,
  `ID_CRITICIDAD` varchar(15) NOT NULL,
  `CRITICIDAD` varchar(45) NOT NULL,
  `ID_EQUIPO` varchar(10) NOT NULL,
  `DESCRIPCION_EQUIPO` varchar(200) NOT NULL,
  `ID_CENTRO_COSTOS` varchar(45) NOT NULL,
  `CENTRO_COSTOS` varchar(45) NOT NULL,
  `ID_AREA` varchar(45) NOT NULL,
  `DESCRIPCION_AREA` varchar(45) NOT NULL,
  `DESCRIPCION_EXTENDIDA` varchar(1000) NOT NULL,
  `FECHA_INICIO` varchar(45) NOT NULL,
  `FECHA_FIN` varchar(45) NOT NULL,
  `OPERACIONES` varchar(2) NOT NULL,
  `MATERIALES` varchar(2) NOT NULL,
  `ID_PUNTO_MEDIDA` varchar(15) DEFAULT NULL,
  `HOJA_RUTA` varchar(15) DEFAULT NULL,
  `PLAN_MTTO` varchar(15) DEFAULT NULL,
  `MONTO_TOTAL_EST` double DEFAULT NULL,
  `MONTO_TOTAL_REAL` double DEFAULT NULL,
  `CREADA_POR` varchar(45) DEFAULT NULL,
